<script setup lang="ts">
// FR-WO-001..004, FR-REVIEW-001/002 / D18-API-027..041 / TC-WO / TC-REVIEW / TC-AUDIT
import {ref,reactive,onMounted,watch} from 'vue';import {useRoute} from 'vue-router';import {get,command,errorText,type Row,type Page} from '../../api/implemented';import {request} from '../../api/http';import {endpoints} from '../../api/endpoints';const send=command(),route=useRoute();
interface Order extends Row {status:string;currentRound:number;orderNo:string;allowedActions:string[];canClose:boolean;validPassId:string|null;submissions:Record<string,unknown>[];reviewTasks:Row[];transferRequests:Row[]}
const rows=ref<Row[]>([]),w=ref<Order|null>(null),history=ref<Row[]>([]),error=ref(''),message=ref(''),busy=ref(false),page=ref(1),total=ref(0),status=ref('');
const form=reactive({assigneeId:'',dueAt:'',reason:'',targetUserId:'',rootCause:'',remediationText:'',result:'PASS',taskId:'',proofEvidenceId:''});const materials=ref<string[]>([]),uploaded=ref<Row[]>([]),file=ref<File|null>(null),uploadKey=ref('');
const labels:Record<string,string>={WAIT_DISPATCH:'待派发',WAIT_CLAIM:'待认领',PROCESSING:'整改中',WAIT_REVIEW:'待复检',CLOSED:'已关闭'};
async function load(){const x=await get<Page>('D18-API-027',{}, {page:String(page.value),size:'20',...(status.value?{status:status.value}:{})});rows.value=x.items;total.value=x.total}
async function select(id:string){w.value=await get<Order>('D18-API-029',{id});history.value=(await get<Page>('D18-API-041',{id},{size:'100'})).items;form.taskId=w.value.reviewTasks.find(t=>t.status==='PENDING')?.id||''}
async function run(f:()=>Promise<unknown>){busy.value=true;error.value='';message.value='';try{await f();await load();if(w.value)await select(w.value.id)}catch(e){error.value=errorText(e)}finally{busy.value=false}}
function base(){return {expectedVersion:w.value!.version,roundNo:w.value!.currentRound}}
async function action(name:string){if(!w.value)return;const id=w.value.id;if(name==='dispatch')await send('D18-API-030',{id},{...base(),assigneeId:form.assigneeId,dueAt:new Date(form.dueAt).toISOString(),reason:form.reason});if(name==='claim')await send('D18-API-031',{id},base());if(name==='transfer')await send('D18-API-032',{id},{...base(),targetUserId:form.targetUserId,reason:form.reason});if(name==='submit'){await send('D18-API-036',{id},{...base(),rootCause:form.rootCause,remediationText:form.remediationText,evidenceIds:materials.value});materials.value=[]}if(name==='task'){const t=await send<Row>('D18-API-037',{id},{...base(),sourceType:'MANUAL'});form.taskId=t.id}if(name==='review')await send('D18-API-038',{id},{...base(),taskId:form.taskId,result:form.result,reason:form.reason,proofEvidenceId:form.result==='ERROR'?null:form.proofEvidenceId});if(name==='close')await send('D18-API-040',{id},{...base(),reviewResultId:w.value.validPassId,reason:form.reason});message.value='操作成功'}
function choose(e:Event){file.value=(e.target as HTMLInputElement).files?.[0]||null;uploadKey.value=crypto.randomUUID()}
async function upload(){if(!file.value||!w.value)return;const body=new FormData();body.append('workOrderId',w.value.id);body.append('file',file.value);const f=await request<Row>(endpoints['D18-API-034'],{},body,{},uploadKey.value);uploaded.value.push(f);materials.value.push(f.id);form.proofEvidenceId=f.id;file.value=null;message.value='材料已上传：'+f.id}
async function download(id:string){const blob=await get<Blob>('D18-API-035',{id});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download='evidence-'+id;link.click();URL.revokeObjectURL(url)}
watch(()=>route.query.order,x=>{if(typeof x==='string')run(()=>select(x))});onMounted(()=>run(async()=>{await load();if(typeof route.query.order==='string')await select(route.query.order)}));
</script><template><section><h2>数据质量问题工单闭环</h2><p class="error" role="alert">{{error}}</p><p role="status">{{message}}</p><div class="actions"><label>状态<select v-model="status" @change="page=1;run(load)"><option value="">全部</option><option v-for="(label,key) in labels" :key="key" :value="key">{{label}}</option></select></label><button :disabled="busy" @click="run(load)">刷新</button></div><table><thead><tr><th>工单 / 问题ID</th><th>状态</th><th>轮次</th><th>责任人ID</th><th>截止时间</th></tr></thead><tbody><tr v-for="o in rows" :key="o.id"><td><button class="link" @click="materials=[];uploaded=[];run(()=>select(o.id))">{{o.orderNo}}</button><br>{{o.issueId}}</td><td>{{labels[String(o.status)]}} <strong v-if="o.overdue">逾期</strong></td><td>{{o.currentRound}}</td><td>{{o.assigneeId||'待派发'}}</td><td>{{o.dueAt||'—'}}</td></tr></tbody></table><div class="actions"><button :disabled="page<=1||busy" @click="page--;run(load)">上一页</button>第{{page}}页 · 共{{total}}条<button :disabled="page*20>=total||busy" @click="page++;run(load)">下一页</button></div><article v-if="w"><h3>{{w.orderNo}}</h3><p>{{labels[w.status]}} · 第{{w.currentRound}}轮 · 版本{{w.version}} <strong v-if="w.overdue">已逾期</strong></p><p v-if="w.coordinationRequired">有待协调的转派申请，当前责任人继续有效。</p><div class="columns"><form v-if="w.allowedActions.includes('dispatch')" @submit.prevent="run(()=>action('dispatch'))"><h3>派发</h3><label>责任人账号ID<input v-model="form.assigneeId" required></label><label>截止时间<input type="datetime-local" v-model="form.dueAt" required></label><label>派单原因<textarea v-model="form.reason" required/></label><button :disabled="busy">派发</button></form><div v-if="w.allowedActions.includes('claim')"><h3>认领工单</h3><button @click="run(()=>action('claim'))" :disabled="busy">认领并开始整改</button></div><form v-if="w.allowedActions.includes('transfer')" @submit.prevent="run(()=>action('transfer'))"><h3>申请转派</h3><label>目标责任人ID<input v-model="form.targetUserId" required></label><label>原因<textarea v-model="form.reason" required/></label><button :disabled="busy">提交待协调申请</button></form></div><div v-if="w.allowedActions.includes('submit')||w.allowedActions.includes('review')"><h3>上传材料</h3><p>候选类型为TXT / PDF，每份不超过10MiB。整改材料和复检材料分别由本人上传。</p><input type="file" accept=".txt,.pdf" @change="choose"><button :disabled="!file||busy" @click="run(upload)">上传至本工单</button><p v-for="f in uploaded" :key="f.id">{{f.originalName}} · 材料ID {{f.id}} <button @click="run(()=>download(f.id))">下载</button></p></div><form v-if="w.allowedActions.includes('submit')" @submit.prevent="run(()=>action('submit'))"><h3>提交第{{w.currentRound}}轮整改</h3><label>根因<textarea v-model="form.rootCause" required maxlength="4000"/></label><label>整改说明<textarea v-model="form.remediationText" required maxlength="8000"/></label><label>本轮材料ID（逗号分隔）<input :value="materials.join(',')" @input="materials=($event.target as HTMLInputElement).value.split(',').map(x=>x.trim()).filter(Boolean)" required></label><button :disabled="busy">提交整改并等待复检</button></form><form v-if="w.allowedActions.includes('review')&&!w.validPassId" @submit.prevent="run(()=>action('review'))"><h3>独立手工复检</h3><p>复检人必须与本轮整改提交人不同。ERROR仅记录技术失败并保留本轮次。</p><button type="button" :disabled="busy||!!form.taskId" @click="run(()=>action('task'))">创建本轮复检任务</button><label>任务ID<input v-model="form.taskId" required readonly></label><label>结论<select v-model="form.result"><option>PASS</option><option>FAIL</option><option>ERROR</option></select></label><label>复检原因<textarea v-model="form.reason" required maxlength="2000"/></label><label v-if="form.result!=='ERROR'">本人上传的复检材料ID<input v-model="form.proofEvidenceId" required></label><button :disabled="busy||!form.taskId">提交复检结论</button></form><form v-if="w.allowedActions.includes('close')" @submit.prevent="run(()=>action('close'))"><h3>关闭工单</h3><p>当前有效PASS：{{w.validPassId}}</p><label>关闭原因<textarea v-model="form.reason" required maxlength="1000"/></label><button :disabled="busy">依据当前PASS关闭</button></form><h3>整改提交快照</h3><div v-for="s in w.submissions" :key="String(s.id)" class="record"><p>第{{s.roundNo}}轮 · 提交人{{s.submittedBy}} · 规则版本{{s.ruleVersionId}}</p><p>{{s.rootCause}}</p><p>{{s.remediationText}}</p><button v-for="f in (s.evidence as Row[])" :key="f.id" @click="run(()=>download(f.id))">{{f.originalName}}</button></div><h3>复检记录</h3><table><tbody><tr v-for="t in w.reviewTasks" :key="t.id"><td>任务{{t.id}}</td><td>{{t.status}}</td><td>{{t.result||'待提交'}}</td><td>{{t.reason}}</td><td><button v-if="t.proofEvidenceId" @click="run(()=>download(String(t.proofEvidenceId)))">下载复检依据</button></td></tr></tbody></table><h3>操作时间线（最近查询最多100条）</h3><ol><li v-for="h in history" :key="h.id">{{h.action}} · {{h.actorId||h.operatorId}} · {{h.createdAt}}<p>{{h.reason}}</p></li></ol></article><p v-if="!rows.length&&!error">当前没有可见工单。</p></section></template>